class SchemaGenerator(BaseSchemaGenerator):
    def __init__(self, base_schema: dict[str, Any]) -> None:
        self.base_schema = base_schema

    def get_schema(self, routes: list[BaseRoute]) -> dict[str, Any]:
        schema = dict(self.base_schema)
        schema.setdefault("paths", {})
        endpoints_info = self.get_endpoints(routes)

        # Determine if QUERY operations should be included (OpenAPI 3.2+)
        openapi_version = schema.get("openapi", "3.0.0")
        try:
            version_parts = list(map(int, openapi_version.split(".")[:2]))
            # OpenAPI 3.2+
            include_query = version_parts[0] == 3 and version_parts[1] >= 2
        except (ValueError, IndexError):
            include_query = False

        for endpoint in endpoints_info:
            # Skip query method for OpenAPI versions before 3.2
            if endpoint.http_method == "query" and not include_query:
                continue

            parsed = self.parse_docstring(endpoint.func)

            if not parsed:
                continue

            if endpoint.path not in schema["paths"]:
                schema["paths"][endpoint.path] = {}

            schema["paths"][endpoint.path][endpoint.http_method] = parsed

        return schema

